import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom'; // <- useNavigate import

export default function Signup() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  function handleSubmit(e) {
    e.preventDefault();
    if (password !== confirm) {
      setError('Passwords do not match');
      return;
    }
    const usersJson = localStorage.getItem('users');
    const users = usersJson ? JSON.parse(usersJson) : [];
    if (users.find(u => u.email === email)) {
      setError('Email already registered.');
      return;
    }
    users.push({ email, password });
    localStorage.setItem('users', JSON.stringify(users));
    const token = btoa(email + ':' + Date.now());
    localStorage.setItem('authToken', token);
    localStorage.setItem('currentUser', JSON.stringify({ email }));
    navigate('/');
  }

  return (
    <div style={{maxWidth:480, margin:'40px auto', padding:20}}>
      <h2>Sign up</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Email</label>
          <input value={email} onChange={e => setEmail(e.target.value)} required type="email" />
        </div>
        <div style={{marginTop:8}}>
          <label>Password</label>
          <input value={password} onChange={e => setPassword(e.target.value)} required type="password" />
        </div>
        <div style={{marginTop:8}}>
          <label>Confirm Password</label>
          <input value={confirm} onChange={e => setConfirm(e.target.value)} required type="password" />
        </div>
        {error && <div style={{color:'red',marginTop:8}}>{error}</div>}
        <div style={{marginTop:12}}>
          <button type="submit">Create account</button>
        </div>
      </form>
      <p style={{marginTop:12}}>Already have an account? <Link to="/login">Log in</Link></p>
    </div>
  );
}
